func check_match(ctx Context, pat, val Value) func(*bool, *Value, *Value, *[]Value) {
	if c := cast[*__wildcard](ctx); c != nil {}

	var trail = truly(ctx, propReversal)
	var k = rxLC.ReplaceAllString(sf("%v %v %v", pat, val, trail), "=")

	if fmt_slot.MatchString(k) { k = sf(k, testdata_s, strings.Split(testdata_s, pathSep)) }

	return func(_matched *bool, _res, _rem *Value, _stems *[]Value) {
		if truly(ctx, is_swapped{}) { return }

		var t = rxLC.ReplaceAllString(sf("%v %v %v %v", *_matched, *_res, *_rem, *_stems), "=")
		var kt = sf("`%s`:`%s`,", k, t)
		if v := checkpoints_match[k]; v == nil {
			if true { prompt(ctx, "	`%s`:`%s`, //match\n", k, t) } else
			{ debug(pc(ctx,pat), _f(`%s`, kt), _f("pat: %v", ts(pat)), _f("val: %v", ts(val)),
				callstack{num:10}, trace{}) }
		} else if v != t {
			debug(pc(ctx,pat), _f(`%s`, k), _f("got: %s", t), _f("!= : %s", v),
				callstack{num:10}, trace{})
		}
	}
}

