func check_matchCompComp(ctx Context, elems, vals []Value, idx int, trail bool) func(*bool, *Value, *Value, *int) {
	var k = sf("%v %v %v %v", elems, vals, idx, trail)
	var v = checkpoints_matchCompComp[k]
	return func(_matched *bool, _res, _rem *Value, _idx *int) {
		if t := sf("%v %v %v %v", *_matched, *_res, *_rem, *_idx); v == nil {
			if true { prompt(ctx, `	"%s":"%s", //matchCompComp`+"\n", k, t) } else
			{ debug(pc(ctx,elems), _f(`"%s":"%s",`, k, t), _f("elems: %v", ts(elems)), _f("vals: %v", ts(vals)),
				callstack{num:16}, trace{}) }
		} else if v != t {
			debug(pc(ctx,elems), _f(`"%s": "%s" != "%s" // len(vals)=%v`, k, t, v, len(vals)), _f("elems: %v", ts(elems)), _f("vals: %v", ts(vals)),
				callstack{num:16}, trace{})
		}
	}
}

