func check_matchGlobPath(ctx Context, elems, segments []Value, idx int, trail bool) func(*bool, *Value, *Value, *[]Value, *int, *token) {
	var ss string
	if len(segments) == 1 {
		if p, ok := unloc(segments[0]).(*punct); ok {
			switch p.token {
			case PROOT: ss = "[ROOT]"
			case PTAIL: ss = "[TAIL]"
			}
		}
	}
	if ss == "" { ss = sf("%v", segments) }

	var k = sf("%v %v %v %v", elems, ss, idx, trail)
	var v = checkpoints_matchGlobPath[k]
	return func(_matched *bool, _res, _rem *Value, _stems *[]Value, _idx *int, _wildToken *token) {
		if t := sf("%v %v %v %v %v %v", *_matched, *_res, *_rem, *_stems, *_idx, *_wildToken); v == nil {
			if true { prompt(ctx, `	"%s":"%s", //matchGlobPath`+"\n", k, t) } else
			{ debug(pc(ctx,elems), _f(`"%s":"%s",`, k, t), _f("elems: %v", ts(elems)), _f("segments: %v", ts(segments)),
				callstack{num:10}, trace{}) }	
		} else if v != t {
			{ debug(pc(ctx,elems), _f(`"%s": "%s" != "%s"`, k, t, v), _f("elems: %v", ts(elems)), _f("segments: %v", ts(segments)),
				callstack{num:10}, trace{}) }
		}
	}
}

