func check_matchPathPath(ctx Context, elems, segments []Value, idx int, trail bool) func(*bool, *Value, *Value, *[]Value, *int) {
	var k = sf("%v %v %v %v", elems, segments, idx, trail)
	var v = checkpoints_matchPathPath[k]
	return func(_matched *bool, _res, _rem *Value, _stems *[]Value, _idx *int) {
		if t := sf("%v %v %v %v %v", *_matched, *_res, *_rem, *_stems, *_idx); v == nil {
			if true { prompt(ctx, `	"%s":"%s", //matchPathPath`+"\n", k, t) } else
			{ debug(pc(ctx,elems), _f(`"%s":"%s",`, k, t), _f("elems: %v", ts(elems)), _f("segments: %v", ts(segments)),
				callstack{num:10}, trace{}) }
		} else if v != t {
			debug(pc(ctx,elems), _f(`"%s": "%s" != "%s"`, k, t, v), _f("elems: %v", ts(elems)), _f("segments: %v", ts(segments)),
				callstack{num:10}, trace{})
		}
	}
}

