func check_cache(ctx Context, k any, c0 string, c *valcache, r []*valcache) {
	var (
		ks = sf("%v %s", c0, k)
		vs = sf("%v %v", c, r)
		rs, y = checkpoints_cache[typeof(k)][ks]
	)
	if !y {
		debug(ctx, "%s: `%s`:`%s`,", typeof(k), ks, vs, trace{})
	} else if vs != rs {
		debug(ctx, _f("%s: %v", typeof(k), ks), _f("%v != %v", vs, rs), trace{})
	}
}

